#!/usr/bin/env bash
set -e
echo "Wiring up final backend APIs: reminders, dashboard, and taken/skipped tracking..."

echo "  api/reminders.js"
mkdir -p "$(dirname 'api/reminders.js')"
echo '' | base64 --decode > 'api/reminders.js'

echo "  api/dashboard.js"
mkdir -p "$(dirname 'api/dashboard.js')"
echo '' | base64 --decode > 'api/dashboard.js'

echo "  lib/localNotifications.js"
mkdir -p "$(dirname 'lib/localNotifications.js')"
echo '' | base64 --decode > 'lib/localNotifications.js'

echo "  lib/medicationTime.js"
mkdir -p "$(dirname 'lib/medicationTime.js')"
echo '' | base64 --decode > 'lib/medicationTime.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "  components/ReminderCard.js"
mkdir -p "$(dirname 'components/ReminderCard.js')"
echo '' | base64 --decode > 'components/ReminderCard.js'

echo "  screens/InputMedicationsScreen.js"
mkdir -p "$(dirname 'screens/InputMedicationsScreen.js')"
echo '' | base64 --decode > 'screens/InputMedicationsScreen.js'

echo "  screens/MedicationReminderScreen.js"
mkdir -p "$(dirname 'screens/MedicationReminderScreen.js')"
echo '' | base64 --decode > 'screens/MedicationReminderScreen.js'

echo "  screens/ConfirmAppointmentScreen.js"
mkdir -p "$(dirname 'screens/ConfirmAppointmentScreen.js')"
echo '' | base64 --decode > 'screens/ConfirmAppointmentScreen.js'

echo "  screens/HomeScreen.js"
mkdir -p "$(dirname 'screens/HomeScreen.js')"
echo '' | base64 --decode > 'screens/HomeScreen.js'

echo "Done."
echo "New: api/reminders.js, api/dashboard.js, components/ReminderCard.js"
echo "Updated: App.js, lib/localNotifications.js, lib/medicationTime.js,"
echo "         screens/InputMedicationsScreen.js, screens/MedicationReminderScreen.js,"
echo "         screens/ConfirmAppointmentScreen.js, screens/HomeScreen.js"
